-- NexoApp · 26 actividades de ejemplo más (28 oct a 23 dic 2026). Ficticias.
-- Para bases de datos que ya tienen el seed original. Es seguro correrlo varias veces:
-- no inserta una actividad si ya existe otra con el mismo título y fecha.
-- Ejecútalo DESPUÉS de schema.sql.
insert into public.activities (cat, title, host, loc, place, lat, lng, date, time, total, base_taken, description, status)
