  ('aprender', 'Marketing digital para emprendedores', 'Camila Torres', 'Suba', 'Casa de la Cultura de Suba', 4.7412, -74.0911, '2026-11-24', '18:00', 30, 16, 'Redes sociales, WhatsApp Business y primeras ventas en línea, con ejemplos de negocios del barrio.'),
